window.I18N_DATA = {"lang":"fr","ui":{"tagline":"Premier semestre dans un nouveau lycée. Les choix que tu feras après les cours changeront la distance entre toi et elles.","nameLabel":"Nom du héros","newGame":"Nouvelle partie","continue":"Continuer","gallery":"Galerie","notice":"Un drame scolaire accessible dès 15 ans. Une partie dure environ 40 à 70 minutes, 7 fins.","updateNotice":"Mise à jour : le jour du festival (Day 5) a été ajouté. Les sauvegardes de progression de l’ancienne version seront réinitialisées, mais la galerie et les fins déjà vues sont conservées.","save":"Sauvegarder","load":"Charger","backlog":"Historique","auto":"Auto","autoOn":"Auto en cours","skip":"Passer","skipOn":"Passage en cours","continueChapter":"Continuer","close":"Fermer","back":"Retour","galleryView":"Voir la galerie","toTitle":"Retour au titre","restart":"Recommencer depuis le début","lockedScene":"Scène pas encore découverte","noRecord":"Aucun enregistrement.","endingsSeen":"Fins vues : {n} / 7","savePrompt":"Entre le numéro de l’emplacement de sauvegarde (1, 2, 3)","loadPrompt":"Entre le numéro de l’emplacement à charger (1, 2, 3)","savedMsg":"Sauvegardé dans l’emplacement {slot}.","noSaveMsg":"Aucune progression sauvegardée. Dans la version mise à jour, les anciennes sauvegardes de progression ont été réinitialisées.","noSlotMsg":"Aucune sauvegarde dans cet emplacement. Dans la version mise à jour, les anciennes sauvegardes de progression ont été réinitialisées.","finalAff":"Affection finale : Seoyeon {sv} / Chaerin {cv} / Arin {av}","defaultName":"Dohyun Kim","endingFallback":"Fin","intro":"Une histoire sur les cinq jours après les cours du premier semestre dans un nouveau lycée. Seoyeon Han, déléguée, Chaerin Moon, du comité de la bibliothèque, et Arin Noh, du club radio. Les choix mènent à sept fins.","autosaveHint":"Continuer charge la sauvegarde automatique, conservée environ toutes les 5 secondes. Elle est distincte des trois emplacements.","settings":"Réglages","toTitleShort":"Titre","textSpeed":"Vitesse du texte","autoWait":"Attente auto","speedSlow":"Lente","speedNormal":"Normale","speedFast":"Rapide","waitShort":"Courte","waitNormal":"Normale","waitLong":"Longue","emptySlot":"Emplacement vide","slotLabel":"Emplacement {n}","overwriteAsk":"Écraser cette sauvegarde ?","overwriteYes":"Écraser","cancel":"Annuler","dayPrologue":"Prologue","dayNum":"Day {n}","dayNight":"Day {n} · Nuit","dayEnding":"Fin","choiceLabel":"Choix","titleConfirm":"Revenir à l’écran titre ?","titleConfirmBody":"La progression est sauvegardée automatiquement.","leaveYes":"Revenir","previewEmpty":"Pas de réplique","linkAbout":"Présentation","linkChars":"Personnages","linkContact":"Contact","linkPrivacy":"Confidentialité"},"sp":{"나":"Moi","서연":"Seoyeon","채린":"Chaerin","아린":"Arin","선생님":"Professeur","학생":"Élève"},"chapters":{"N1_01":"Day 1 · La nuit","N2_01":"Day 2 · La nuit","N3_01":"Day 3 · La nuit","D1_01_01":"Day 1 · Premier jour dans un nouveau lycée","D2_01_01":"Day 2 · La distance se réduit","D3_01_01":"Day 3 · Préparatifs du festival","D4_01_01":"Day 4 · La veille du festival","D5_01_01":"Day 5 · Le jour du festival"},"endings":{"SY_GOOD":"Bonne fin de Seoyeon : Après les cours, avec toi","SY_NORMAL":"Fin normale de Seoyeon : Les règles ne changent pas","CH_GOOD":"Bonne fin de Chaerin : La place près de la fenêtre, pour deux","CH_NORMAL":"Fin normale de Chaerin : Au rythme d’une lecture lente","AR_GOOD":"Bonne fin d’Arin : Pas une réservation, une confirmation","AR_NORMAL":"Fin normale d’Arin : Un compte rendu officiel","SOLO":"Fin solo : Adaptation au semestre terminée"},"endingShort":{"SY_GOOD":"Bonne · Seoyeon","SY_NORMAL":"Normale · Seoyeon","CH_GOOD":"Bonne · Chaerin","CH_NORMAL":"Normale · Chaerin","AR_GOOD":"Bonne · Arin","AR_NORMAL":"Normale · Arin","SOLO":"Solo"},"cg":{"cg01":"Devant la porte de la classe, un premier regard","cg02":"À la bibliothèque, à portée de main","cg03":"Sous le soleil couchant, des remerciements tardifs","cg04":"Émission du festival, un casque tendu","cg05":"Clôture, les trois filles dans le crépuscule"},"steps":{"P01_01":{"tx":"Printemps, premier jour dans mon nouveau lycée.","sp":"Moi"},"P01_02":{"tx":"Le matin, dans ce quartier où je viens d’emménager, tout me semble encore étranger.","sp":"Moi"},"P01_03":{"tx":"En suivant la rue où tourbillonnent les pétales de cerisier, le portail de mon nouveau lycée se rapproche.","sp":"Moi"},"P01_04":{"tx":"Honnêtement, je suis un peu nerveux.","sp":"Moi"},"P01_05":{"tx":"Nouvelle classe, nouvelle place, nouveaux visages.","sp":"Moi"},"P01_06":{"tx":"Je franchis le portail avec une seule idée en tête : passer cette journée sans encombre.","sp":"Moi"},"P01_07":{"tx":"Devant les casiers à chaussures, je vérifie encore une fois le tableau d’affectation.","sp":"Moi"},"P01_08":{"tx":"Première, classe 1. La salle est la deuxième au bout du couloir.","sp":"Moi"},"P02_01":{"tx":"Devant la porte de la classe. Je respire un grand coup et m’apprête à l’ouvrir.","sp":"Moi"},"P02_02":{"tx":"Mais la porte s’ouvre d’elle-même, de l’intérieur.","sp":"Moi"},"P02_03":{"tx":"Une élève tenant des dossiers, et nos regards se croisent, face à face.","sp":"Moi"},"P02_04":{"tx":"Euh... c’est toi, la personne transférée ?","sp":"Seoyeon"},"P02_05":{"tx":"De longs cheveux brun foncé. Un uniforme impeccable. Et un regard droit, sans détour.","sp":"Moi"},"P02_06":{"tx":"C’est bien ça. Première 1, je suis Han Seoyeon, la déléguée de classe.","sp":"Seoyeon"},"P02_07":{"tx":"Aujourd’hui, c’est moi qui m’occupe de guider la personne transférée.","sp":"Seoyeon"},"P02_08":{"choices":["La saluer d’abord poliment","Vérifier son badge et la saluer"]},"P02_09":{"tx":"Bonjour, je m’appelle {name}. Je compte sur toi aujourd’hui.","sp":"Protagoniste"},"P02_10":{"tx":"Tu peux me parler normalement, tu sais. On est dans la même classe.","sp":"Seoyeon"},"P02_11":{"tx":"Par contre, avant de te perdre, viens me voir moi d’abord. C’est la règle.","sp":"Seoyeon"},"P02_12":{"tx":"« La règle », dit-elle. Très déléguée de classe. Et pourtant, elle ne me fait pas peur.","sp":"Moi"},"P03_01":{"tx":"Voici qui rejoint notre classe à partir d’aujourd’hui.","sp":"Professeur"},"P03_02":{"tx":"Devant l’estrade. Tous les regards de la classe se tournent vers moi d’un coup.","sp":"Moi"},"P03_03":{"choices":["Se présenter brièvement et clairement","Se présenter avec une petite blague"]},"P03_04":{"tx":"Je m’appelle {name}. Au plaisir de faire votre connaissance.","sp":"Protagoniste"},"P03_05":{"tx":"C’est encore Seoyeon qui m’a indiqué ma place.","sp":"Moi"},"P03_06":{"tx":"Ta place, c’est la deuxième depuis le fond, près de la fenêtre. On ira chercher tes manuels ensemble avant le déjeuner.","sp":"Seoyeon"},"P03_07":{"tx":"C’est ainsi que commença mon premier jour dans ce lycée.","sp":"Moi"},"D1_01_01":{"tx":"Premier cours. Mais on ne récupérera les manuels que cet après-midi, paraît-il.","sp":"Moi"},"D1_01_02":{"tx":"Je regarde mon bureau vide, quand un manuel glisse doucement vers moi, depuis la place voisine.","sp":"Moi"},"D1_01_03":{"tx":"Pour aujourd’hui, regarde dans le mien. De toute façon, c’est moi qui prends toutes les notes.","sp":"Seoyeon"},"D1_01_04":{"tx":"Sa main déplie le livre en deux avec un geste habitué. La main de quelqu’un qui a l’habitude de s’occuper des autres.","sp":"Moi"},"D1_01_05":{"choices":["La remercier et regarder avec elle","Dire que ça va et tenir bon sans aide"]},"D1_01_06":{"tx":"Après le cours, prends mes notes en photo. C’est ton devoir du jour.","sp":"Seoyeon"},"D1_01_07":{"tx":"Pour ce premier cours, ce sont les petits caractères de ma voisine qui m’ont plus marqué que les explications du professeur.","sp":"Moi"},"D1_02_01":{"tx":"Pause déjeuner. Une voix joyeuse sort du haut-parleur du lycée.","sp":"Moi"},"D1_02_02":{"tx":"L’émission du midi, voici les nouvelles du jour. Il paraît que quelqu’un vient d’être transféré dans notre lycée.","sp":"Arin"},"D1_02_03":{"tx":"{name}, de première 1. Le club radio réserve sa toute première interview.","sp":"Arin"},"D1_02_04":{"tx":"Les regards de la classe se tournent à nouveau vers moi. À qui appartient cette voix, au juste ?","sp":"Moi"},"D1_02_05":{"tx":"Après l’émission, devant le studio radio au bout du couloir, je tombe sur la propriétaire de la voix.","sp":"Moi"},"D1_02_06":{"tx":"Trouvé ! C’est bien toi, qui arrives de l’autre classe ?","sp":"Arin"},"D1_02_07":{"tx":"Je suis Noh Arin, en seconde, au club radio. La voix de l’émission du midi, c’était moi.","sp":"Arin"},"D1_02_08":{"tx":"Tu as l’air tout tendu. Souris, allez, souris. Une interview, ce n’est pas effrayant.","sp":"Arin"},"D1_02_09":{"choices":["Accepter l’interview en souriant","Lui demander d’attendre un autre jour"]},"D1_02_10":{"tx":"Parfait, cette réaction. Un jour, je m’en servirai pour mon interview numéro un, c’est sûr.","sp":"Arin"},"D1_02_11":{"tx":"Une pause déjeuner où une élève que je venais de rencontrer m’avait déjà réservé une interview.","sp":"Moi"},"D1_03_01":{"tx":"Après les cours. Je passe à la bibliothèque chercher la liste de livres recommandés, nécessaire pour mon dossier de transfert.","sp":"Moi"},"D1_03_02":{"tx":"Entre les hautes étagères, près de la fenêtre, une aînée aux longs cheveux lit un livre.","sp":"Moi"},"D1_03_03":{"tx":"J’ai trouvé le premier livre de la liste. Au moment de tendre la main, une autre main a failli toucher le même livre, de l’autre côté.","sp":"Moi"},"D1_03_04":{"tx":"Nos deux mains s’arrêtent sur le livre. Et nos regards se tournent, non vers le livre, mais l’un vers l’autre.","sp":"Moi"},"D1_03_05":{"tx":"... Tu cherchais ce livre, toi aussi ?","sp":"Chaerin"},"D1_03_06":{"tx":"Moon Chaerin, en terminale. Je suis membre du comité de la bibliothèque.","sp":"Chaerin"},"D1_03_07":{"choices":["Donner le titre du livre et demander son aide","Chercher encore un peu seul dans les rayonnages"]},"D1_03_08":{"tx":"Tu es la première personne transférée à choisir ce livre. Je vais t’aider à finir ta liste.","sp":"Chaerin"},"D1_03_09":{"tx":"À une condition. Ne deviens jamais le genre de personne qui commence un livre par la dernière page.","sp":"Chaerin"},"D1_03_10":{"tx":"La bibliothèque est silencieuse. Et pourtant, cette phrase me reste longtemps dans les oreilles.","sp":"Moi"},"D1_04_01":{"tx":"Dans le couloir, avant de rentrer. Naturellement, un choix s’impose : avec qui terminer cette journée ?","sp":"Moi"},"D1_04_02":{"choices":["Ranger le panneau d’affichage de la classe avec Seoyeon","Finir de choisir les livres recommandés avec Chaerin","Accepter la demande d’interview d’Arin"]},"D1_04_S1":{"tx":"Tu vas m’aider à ranger le panneau d’affichage ? Dès ton premier jour, tu n’as pas de chance.","sp":"Seoyeon"},"D1_04_S2":{"tx":"... Merci. Honnêtement, il y en avait vraiment beaucoup.","sp":"Seoyeon"},"D1_04_S3":{"tx":"À deux, c’était fini en un rien de temps. Les épaules de la déléguée semblent un peu plus légères.","sp":"Moi"},"D1_04_C1":{"tx":"Le reste de la liste, on le choisit selon tes goûts. Alors, quels sont tes goûts ?","sp":"Chaerin"},"D1_04_C2":{"tx":"Cette réponse me plaît. Demain, des nouveautés arrivent au bac de retour. Tu peux passer les voir.","sp":"Chaerin"},"D1_04_C3":{"tx":"Je quitte la bibliothèque avec trois livres dans les bras. Mais ce sont les mots de l’aînée qui me restent le plus.","sp":"Moi"},"D1_04_A1":{"tx":"C’est une vraie interview, à partir de maintenant. Première question. Le premier jour de ton transfert, qui t’a le plus marqué ?","sp":"Arin"},"D1_04_A2":{"tx":"Euh, cette réponse-là... je vais la garder pour ma collection personnelle. Interdite d’antenne.","sp":"Arin"},"D1_04_A3":{"tx":"Je ne sais même pas ce que j’ai dit. Mais les oreilles de la cadette étaient un peu rouges.","sp":"Moi"},"D2_01_01":{"tx":"Deuxième jour, le matin. Sur le chemin du lycée, une voix familière m’appelle par-derrière.","sp":"Moi"},"D2_01_02":{"tx":"L’émission d’hier a eu beaucoup de succès. Il paraît que l’annonce de ton interview a reçu des demandes.","sp":"Arin"},"D2_01_03":{"tx":"Alors pas question de t’enfuir. L’interview numéro un est pour moi.","sp":"Arin"},"D2_01_04":{"choices":["Lui dire franchement ce que j’en ai pensé","Éluder, un peu gêné"]},"D2_01_05":{"tx":"C’était un peu gênant. Mais ce n’était pas désagréable.","sp":"Protagoniste"},"D2_01_06":{"tx":"Arin hoche la tête, satisfaite, et part en courant devant. Une cadette bien occupée.","sp":"Moi"},"D2_02_01":{"tx":"En cours, un travail de groupe est annoncé.","sp":"Moi"},"D2_02_02":{"tx":"Je m’occupe des recherches, du tri... ça aussi, je le ferai. Et le texte de la présentation aussi.","sp":"Seoyeon"},"D2_02_03":{"tx":"Cette habitude de tout porter toute seule. Je l’avais déjà vue hier, devant le panneau d’affichage.","sp":"Moi"},"D2_02_04":{"choices":["Proposer le premier de partager les tâches","Attendre que Seoyeon ait fini de tout organiser"]},"D2_02_05":{"tx":"... Partager, c’était donc quelque chose d’aussi naturel.","sp":"Seoyeon"},"D2_02_06":{"tx":"Alors, le brouillon de la présentation, je peux te le confier ? Cette fois, c’est moi qui te demande un service.","sp":"Seoyeon"},"D2_02_07":{"tx":"Un cours passé à regarder, depuis la place voisine, la déléguée apprendre à demander de l’aide.","sp":"Moi"},"D2_03_01":{"tx":"À la pause déjeuner, dans l’espace détente devant la bibliothèque. Chaerin tient le livre emprunté hier.","sp":"Moi"},"D2_03_02":{"tx":"Ce livre d’hier, Le premier chemin. À la page 12, il y a ce passage.","sp":"Chaerin"},"D2_03_03":{"tx":"« Sur un chemin qu’on emprunte pour la première fois, les pas d’un autre deviennent une carte. »","sp":"Chaerin"},"D2_03_04":{"tx":"J’ai pensé que ce passage t’irait bien, à toi qui viens d’arriver.","sp":"Chaerin"},"D2_03_05":{"choices":["Réciter le passage et le lui redemander","Avouer franchement que je ne m’en souviens pas"]},"D2_03_06":{"tx":"... S’en souvenir, ou être honnête. Aucune des deux n’est une mauvaise réponse.","sp":"Chaerin"},"D2_03_07":{"tx":"L’aînée me tend un marque-page. Un vieux marque-page en cuir.","sp":"Moi"},"D2_03_08":{"tx":"Je te le prête. Quand tu auras fini de lire, reviens me le rendre.","sp":"Chaerin"},"D2_04_01":{"tx":"Après les cours. Aujourd’hui encore, un choix m’attend dans le couloir.","sp":"Moi"},"D2_04_02":{"choices":["Trier les comptes rendus de réunion du festival avec Seoyeon","Aider Chaerin à ranger les nouveautés de la bibliothèque","Servir de partenaire d’entraînement pour l’interview d’Arin"]},"D2_04_S1":{"tx":"Le festival est dans trois jours. Les comptes rendus forment une montagne. Tu t’y attendais, j’espère ?","sp":"Seoyeon"},"D2_04_S2":{"tx":"À deux, tout est divisé par deux, le temps comme le travail. C’est une drôle de sensation, dans le bon sens.","sp":"Seoyeon"},"D2_04_S3":{"tx":"Sur la dernière page du compte rendu, Seoyeon écrit en petit : « La prochaine réunion, à deux. »","sp":"Moi"},"D2_04_C1":{"tx":"Ranger les nouveautés, c’est un travail silencieux. Le silence te va bien.","sp":"Chaerin"},"D2_04_C2":{"tx":"La place près de la fenêtre, normalement, je l’occupe seule. Mais j’ai l’impression qu’une étagère de plus vient de s’y ajouter.","sp":"Chaerin"},"D2_04_C3":{"tx":"Avant que je puisse demander ce que ça voulait dire, l’aînée s’était déjà retournée. Je chercherai la réponse demain.","sp":"Moi"},"D2_04_A1":{"tx":"Pour l’entraînement, trois questions seulement. La personne à laquelle tu penses le plus en ce moment, c’est qui ?","sp":"Arin"},"D2_04_A2":{"tx":"... Cette question, c’était mon erreur. Faisons comme si je n’avais pas entendu la réponse. Moi seule m’en souviendrai.","sp":"Arin"},"D2_04_A3":{"tx":"L’entraînement s’arrête là. Dans le carnet de la cadette, quelque chose de long avait été écrit.","sp":"Moi"},"D3_01_01":{"tx":"Troisième jour. Pendant l’appel du matin, le programme du festival est annoncé.","sp":"Moi"},"D3_01_02":{"tx":"Pour préparer le festival, chaque classe travaillera par binômes. Choisissez votre partenaire d’ici la veille du festival.","sp":"Professeur"},"D3_01_03":{"tx":"Je récupère les formulaires de partenariat. Si quelqu’un hésite... je peux aussi donner des conseils.","sp":"Seoyeon"},"D3_01_04":{"tx":"Annonce du club radio. Les candidatures pour animer l’émission du festival sont reçues par notre club.","sp":"Arin"},"D3_01_05":{"tx":"Partenaire de festival. Au bout de trois jours à peine, voilà déjà des choses à décider.","sp":"Moi"},"D3_02_01":{"tx":"Après les cours, direction la bibliothèque, pour rendre le marque-page.","sp":"Moi"},"D3_02_02":{"tx":"Tu tombes bien. En fait, un livre a disparu du bac de retour.","sp":"Chaerin"},"D3_02_03":{"tx":"C’est un livre que je gardais précieusement pour l’exposition du festival. Seule, ça risque de me prendre du temps à le retrouver.","sp":"Chaerin"},"D3_02_04":{"choices":["Proposer de le chercher ensemble","Proposer de prévenir le comité de la bibliothèque"]},"D3_02_05":{"tx":"Merci. Il y a un indice. Ce serait près des rayonnages où on a rangé les nouveautés hier.","sp":"Chaerin"},"D3_02_06":{"tx":"La recherche du livre allait se prolonger après les cours.","sp":"Moi"},"D3_03_01":{"tx":"À la pause déjeuner, il y a de l’agitation devant le studio radio.","sp":"Moi"},"D3_03_02":{"tx":"C’est la catastrophe. Les pages du script de l’émission sont toutes mélangées.","sp":"Arin"},"D3_03_03":{"tx":"L’émission est dans cinq minutes. Moi, ce genre d’erreur, c’est la première fois...","sp":"Arin"},"D3_03_04":{"choices":["Trier le script ensemble et remettre les pages dans l’ordre","Dire que je vais chercher un professeur"]},"D3_03_05":{"tx":"Ça y est, l’ordre est rétabli. L’émission, je m’en occupe. Toi, reste à côté et regarde-moi faire.","sp":"Arin"},"D3_03_06":{"tx":"D’une main tremblante, la cadette allume le micro. L’émission se termine sans problème.","sp":"Moi"},"D3_03_07":{"tx":"Après les cours, on refait une prise. Là, je te remercierai comme il faut.","sp":"Arin"},"D3_04_01":{"tx":"Après les cours. La date limite pour confirmer les partenaires du festival, c’est demain, la veille du festival.","sp":"Moi"},"D3_04_02":{"tx":"Il est temps de décider où aller.","sp":"Moi"},"D3_04_03":{"choices":["Aider Seoyeon jusqu’au bout avec les papiers du festival","Chercher le livre disparu avec Chaerin jusqu’au bout","Aider Arin pour sa nouvelle prise et fixer la promesse"]},"D3_04_S1":{"tx":"Il y a trois cartons de papiers. On peut vraiment finir aujourd’hui, nous deux ?","sp":"Seoyeon"},"D3_04_S2":{"tx":"« Nous », je l’ai dit, moi, là. ... Pas d’annulation, d’accord ?","sp":"Seoyeon"},"D3_04_S3":{"tx":"Quand tous les papiers furent rangés, dehors, la lumière était déjà celle du couchant.","sp":"Moi"},"D3_04_C1":{"tx":"Commençons par l’arrière des rayonnages. Sans faire de bruit, et en retenant l’ordre des couleurs des dos de livres.","sp":"Chaerin"},"D3_04_C2":{"tx":"Le voilà, ici. À deux, on le retrouve plus vite, décidément.","sp":"Chaerin"},"D3_04_C3":{"tx":"L’expression de l’aînée, tenant le livre retrouvé contre elle, était la plus douce que j’aie vue aujourd’hui.","sp":"Moi"},"D3_04_A1":{"tx":"Dernière question de la nouvelle prise. Le festival, tu veux le passer avec qui ?","sp":"Arin"},"D3_04_A2":{"tx":"Cette réponse, elle n’est pas pour l’antenne. Je vais l’écrire comme une promesse, dans mon carnet.","sp":"Arin"},"D3_04_A3":{"tx":"La cadette écrit quelque chose avec application dans son carnet. J’ai pu voir deux mots : « promesse ».","sp":"Moi"},"D5_01_01":{"tx":"Le matin du festival. Dès que je franchis le portail, je sens un air différent de la veille.","sp":"Moi"},"D5_01_02":{"tx":"Au bord de la cour, les tentes des stands s’alignent, et les banderoles flottent au vent.","sp":"Moi"},"D5_01_03":{"tx":"Tous les papiers et toutes les répétitions accumulés jusqu’à hier, c’était pour aujourd’hui.","sp":"Moi"},"D5_01_04":{"tx":"Annonce. Dans quelques instants, à 9 heures, commencera la cérémonie d’ouverture du festival.","sp":"Arin"},"D5_01_05":{"tx":"À travers le haut-parleur, la voix d’Arin est bien plus assurée qu’à la répétition d’hier.","sp":"Moi"},"D5_01_06":{"tx":"{name}, tu es arrivé tôt. Avant l’ouverture, faisons juste un tour pour vérifier les stands, ensemble.","sp":"Seoyeon"},"D5_01_07":{"tx":"La déléguée, sa liste de contrôle et son stylo à la main. Aujourd’hui encore, ses épaules sont un peu tendues.","sp":"Moi"},"D5_01_08":{"tx":"Et pourtant, aujourd’hui, je tremble moins qu’hier. Peut-être parce qu’il y a un visage familier à côté de moi.","sp":"Seoyeon"},"D5_01_09":{"tx":"En faisant le tour des stands, nous passons devant le panneau de l’exposition de livres. À la place du premier livre, un petit écriteau manuscrit est accroché.","sp":"Moi"},"D5_01_10":{"tx":"« La première page, à ouvrir ensemble. » Une phrase digne de Chaerin.","sp":"Moi"},"D5_01_11":{"tx":"Du côté du stand radio, Arin agite la main. Sa carte de membre, accrochée à son cou, brille au soleil.","sp":"Moi"},"D5_01_12":{"tx":"La cloche d’ouverture sonne. Le festival commence.","sp":"Moi"},"D5_01_13":{"choices":["Faire un tour pour sentir l’ambiance de l’ouverture","Passer d’abord par le stand le plus proche","Respirer profondément et repasser le programme de la journée"]},"D5_02_01":{"tx":"Trente minutes après l’ouverture. Devant le stand de limonade de la classe 1, une file s’est déjà formée.","sp":"Moi"},"D5_02_02":{"tx":"Les commandes, dans l’ordre, s’il vous plaît. Pas besoin de se presser.","sp":"Seoyeon"},"D5_02_03":{"tx":"Sa voix est calme, mais la main qui tient les bons de commande ne s’arrête pas une seconde.","sp":"Moi"},"D5_02_04":{"tx":"Excusez-moi, la limonade n’est toujours pas là. Ça fait un moment que j’attends.","sp":"Élève"},"D5_02_05":{"tx":"À l’heure de pointe, deux bons de commande se sont mélangés. Au bout de la file, les murmures grossissent.","sp":"Moi"},"D5_02_06":{"tx":"Pardonnez-moi. Je vérifie tout de suite. Patientez un instant, s’il vous plaît.","sp":"Seoyeon"},"D5_02_07":{"choices":["Se placer au bout de la file et guider calmement l’ordre","Étaler les bons de commande avec Seoyeon, à côté d’elle"]},"D5_02_08":{"tx":"En remettant les bons dans l’ordre chronologique, les murmures de la file s’apaisent.","sp":"Moi"},"D5_02_09":{"tx":"Voilà, le rythme est revenu. À partir de la prochaine commande, on ne sera plus en retard.","sp":"Seoyeon"},"D5_02_10":{"tx":"Le stand a retrouvé sa cadence, mais Seoyeon n’a toujours pas pu souffler une seule fois.","sp":"Moi"},"D5_02_11":{"tx":"Je revois son image d’hier, ensevelie sous une montagne de papiers. Son habitude de tout garder pour elle plutôt que de demander n’a pas changé.","sp":"Moi"},"D5_02_12":{"tx":"{name}, tu peux aller à ton prochain rendez-vous. Ici, ça ira, maintenant.","sp":"Seoyeon"},"D5_02_13":{"tx":"Contrairement à ses mots, la fin de sa voix tremble légèrement.","sp":"Moi"},"D5_02_14":{"tx":"Je pourrais aussi tourner les talons, là. Mais je repense à la déléguée qui, hier, apprenait à s’appuyer sur quelqu’un.","sp":"Moi"},"D5_02_15":{"choices":["L’aider à côté d’elle jusqu’à ce que la file se résorbe","Croire Seoyeon sur parole et passer au rendez-vous suivant"]},"D5_02_16":{"tx":"... Vraiment, si tu remarques toujours tout avant les autres. Aujourd’hui, c’est moi qui te dirai merci en premier.","sp":"Seoyeon"},"D5_03_01":{"tx":"Vers midi, à la bibliothèque. C’est le dernier jour de l’exposition du festival, il y a plus de monde que d’habitude.","sp":"Moi"},"D5_03_02":{"tx":"Au centre de l’exposition se trouve le livre qui avait disparu du bac de retour, il y a quelques jours, avant d’être retrouvé.","sp":"Moi"},"D5_03_03":{"tx":"Le livre disparu est à la place la plus convoitée. Ironique, non ?","sp":"Chaerin"},"D5_03_04":{"tx":"Pourquoi avez-vous choisi ce livre comme premier livre de l’exposition ?","sp":"Élève"},"D5_03_05":{"tx":"Les questions des visiteurs arrivent toutes en même temps. Pourquoi ce choix, l’histoire de l’auteur, et même la prochaine exposition.","sp":"Moi"},"D5_03_06":{"tx":"Je répondrai une par une. Les histoires de livres, si on se presse, elles perdent de leur charme.","sp":"Chaerin"},"D5_03_07":{"choices":["Mettre les questions en ordre et les passer à l’aînée","Se tenir à côté avec le panneau d’information de l’exposition"]},"D5_03_08":{"tx":"Une fois les questions triées, les réponses de l’aînée s’allongent. Quand il s’agit de livres, c’est quelqu’un qui parle beaucoup.","sp":"Moi"},"D5_03_09":{"tx":"La dernière page de ce livre, tu sais. Chaque lecteur s’en souvient différemment.","sp":"Chaerin"},"D5_03_10":{"tx":"Les visiteurs hochent la tête et ouvrent le livre. L’exposition ressemble bientôt à un petit club de lecture.","sp":"Moi"},"D5_03_11":{"tx":"Les questions se sont espacées, mais sur la place près de la fenêtre de l’aînée, il reste encore la fiche de question d’un prochain visiteur.","sp":"Moi"},"D5_03_12":{"tx":"L’exposition dure jusqu’à cet après-midi. Je compte rester là à veiller jusqu’à la fin.","sp":"Chaerin"},"D5_03_13":{"tx":"Le ton de quelqu’un qui a l’habitude de veiller seul. Mais aujourd’hui, il sonne un peu différemment.","sp":"Moi"},"D5_03_14":{"tx":"Le marque-page n’est pas dans le tiroir de mon bureau, mais dans le sac que j’ai apporté aujourd’hui. Je le rendrai après la fin du festival.","sp":"Moi"},"D5_03_15":{"choices":["Rester à ses côtés pour accueillir jusqu’au dernier visiteur","Faire confiance au rythme de l’aînée et s’éclipser"]},"D5_03_16":{"tx":"... Je n’enlève mes lunettes que quand je veux me concentrer. Aujourd’hui, il y avait une raison de le faire.","sp":"Chaerin"},"D5_04_01":{"tx":"Juste avant l’émission en direct de l’après-midi. Dès que j’ouvre la porte du studio, Arin s’approche en agitant son script.","sp":"Moi"},"D5_04_02":{"tx":"Regarde ça. Sur la dernière ligne du script, les noms des deux animateurs sont écrits côte à côte, tu vois ?","sp":"Arin"},"D5_04_03":{"tx":"Dans le blanc qui était vide hier, aujourd’hui, mon nom est écrit bien nettement.","sp":"Moi"},"D5_04_04":{"tx":"Le blanc, je l’ai rempli ce matin. À l’encre, pour que tu ne puisses pas t’enfuir.","sp":"Arin"},"D5_04_05":{"tx":"Allez, l’émission commence. La présentation du premier morceau, comme on l’a réglée hier, c’est toi qui commences.","sp":"Arin"},"D5_04_06":{"tx":"Le voyant « ON AIR » s’allume. La complicité répétée tant de fois en répétition commence.","sp":"Moi"},"D5_04_07":{"tx":"Mais vers la fin du deuxième morceau, un sifflement aigu éclate dans le haut-parleur.","sp":"Moi"},"D5_04_08":{"tx":"Oh, le fichier son est mélangé. C’est un incident d’antenne, ça.","sp":"Arin"},"D5_04_09":{"choices":["Gagner du temps en parlant et faire un signe à Arin","Ouvrir le segment suivant selon l’ordre de secours du script"]},"D5_04_10":{"tx":"Je n’aurais jamais cru que l’ordre de secours, décidé hier en riant en répétition, servirait vraiment.","sp":"Moi"},"D5_04_11":{"tx":"Le fichier est réparé. Ta voix, elle n’a pas tremblé une seconde.","sp":"Arin"},"D5_04_12":{"tx":"L’émission a repris sans encombre. Il ne reste que le dernier segment et le mot de la fin.","sp":"Moi"},"D5_04_13":{"tx":"La conclusion, je peux la faire seule. Toi, tu as d’autres rendez-vous.","sp":"Arin"},"D5_04_14":{"tx":"Elle le dit avec le sourire, mais le bout de ses doigts, sur le script, retient encore la tension de l’incident de tout à l’heure.","sp":"Moi"},"D5_04_15":{"choices":["Rester sur le siège voisin et terminer la conclusion ensemble","Faire confiance à l’animation d’Arin et quitter le studio"]},"D5_04_16":{"tx":"Je ne regrette pas d’avoir rempli le blanc. Cette émission d’aujourd’hui, je crois que ce sera celle dont je me souviendrai le plus longtemps.","sp":"Arin"},"D5_05_01":{"tx":"Avant le spectacle de l’après-midi sur scène, les gens commencent à se rassembler dans la cour.","sp":"Moi"},"D5_05_02":{"tx":"Mais aucun son ne sort du haut-parleur de la scène. Un câble semble mal branché.","sp":"Moi"},"D5_05_03":{"tx":"Le spectacle commence dans vingt minutes. Je m’occupe d’abord des déplacements du public.","sp":"Seoyeon"},"D5_05_04":{"tx":"L’avis de retard, je vais le peaufiner. Pour que le temps d’attente paraisse plus court.","sp":"Chaerin"},"D5_05_05":{"tx":"Moi, je mets une annonce à l’antenne. Pour que personne ne soit surpris.","sp":"Arin"},"D5_05_06":{"tx":"Le câble débranché est vite retrouvé derrière la scène. Le problème, c’est la suite : avec qui terminer la préparation ?","sp":"Moi"},"D5_05_07":{"tx":"Les regards des trois filles se croisent, un par un. C’est le moment où l’après-midi du festival se partage.","sp":"Moi"},"D5_05_08":{"choices":["Organiser les déplacements de la scène avec Seoyeon","Peaufiner l’avis de retard avec Chaerin","Régler l’annonce d’information avec Arin"]},"D5_05_S1":{"tx":"L’entrée par ici, la sortie de l’autre côté. Pour éviter les confusions, posons d’abord les panneaux.","sp":"Seoyeon"},"D5_05_S2":{"tx":"Pendant qu’on pose les panneaux et qu’on aligne la file, les instructions de la déléguée ne s’interrompent pas une seule fois.","sp":"Moi"},"D5_05_S3":{"tx":"Maintenant que les déplacements sont réglés, mon esprit l’est aussi. On peut commencer.","sp":"Seoyeon"},"D5_05_S4":{"tx":"Les lumières de la scène s’allument. Les applaudissements du public se répandent dans la cour.","sp":"Moi"},"D5_05_S5":{"tx":"Aujourd’hui, du début à la fin, la personne à côté de moi, c’était toujours la même. ... Ce n’est pas un hasard, tout ça.","sp":"Seoyeon"},"D5_05_C1":{"tx":"La première phrase de l’avis, comme ceci : « L’attente aussi fait partie du festival. »","sp":"Chaerin"},"D5_05_C2":{"tx":"La main de l’aînée, qui choisit les phrases, est lente. C’est quelqu’un qui pèse chaque mot.","sp":"Moi"},"D5_05_C3":{"tx":"L’expression que tu as choisie est plus douce. Allons-y avec celle-là.","sp":"Chaerin"},"D5_05_C4":{"tx":"L’avis terminé est affiché au tableau près de la scène. Les visages des gens qui attendent se détendent un peu.","sp":"Moi"},"D5_05_C5":{"tx":"Choisir des phrases avec quelqu’un, c’est une première pour moi. Et ce n’est pas une mauvaise première.","sp":"Chaerin"},"D5_05_A1":{"tx":"L’annonce, et si on la lisait à tour de rôle, toi et moi ? Ça donnerait moins l’impression d’attendre.","sp":"Arin"},"D5_05_A2":{"tx":"Les deux noms écrits dans le blanc du script sont, cette fois, vraiment lus côte à côte.","sp":"Moi"},"D5_05_A3":{"tx":"On est parfaitement en rythme. J’en étais sûre, le blanc, c’était ta place.","sp":"Arin"},"D5_05_A4":{"tx":"À la fin de l’annonce, le signal arrive depuis la scène : le câble est réparé.","sp":"Moi"},"D5_05_A5":{"tx":"L’annonce qu’on a lue ensemble, tout le lycée l’a entendue aujourd’hui, pas vrai ? C’est un peu gênant, mais ça me plaît.","sp":"Arin"},"D5_06_01":{"tx":"Le soleil décline, et le crépuscule s’étend sur les tentes des stands.","sp":"Moi"},"D5_06_02":{"tx":"Annonce de clôture. Merci à tous d’être venus au festival aujourd’hui.","sp":"Arin"},"D5_06_03":{"tx":"Le mot de la fin d’Arin résonne dans la cour. Le script qui avait commencé par un blanc a été lu jusqu’au bout.","sp":"Moi"},"D5_06_04":{"tx":"Il y a eu des incidents, mais tout s’est terminé sans blessé. C’est tout ce qui compte.","sp":"Seoyeon"},"D5_06_05":{"tx":"Et aujourd’hui, j’ai l’impression d’avoir un peu appris à m’appuyer. J’ai quelqu’un sur qui m’appuyer, maintenant.","sp":"Seoyeon"},"D5_06_06":{"tx":"Avant que les gens se dispersent pour ranger la clôture, les lumières de l’exposition de la bibliothèque vont bientôt s’éteindre aussi.","sp":"Moi"},"D5_06_07":{"tx":"Je sors de mon sac le vieux marque-page en cuir. Le festival est fini, il est temps de le rendre, comme promis.","sp":"Moi"},"D5_06_08":{"tx":"Te voilà pour me le rendre. Tu te souviens de ce que j’avais dit, qu’attendre avait son charme ?","sp":"Chaerin"},"D5_06_09":{"tx":"Le marque-page est retourné à sa place d’origine. Mais la place de la personne qui l’avait emprunté... qui sait.","sp":"Chaerin"},"D5_06_10":{"tx":"Quand j’ouvrirai le prochain livre, j’aimerais que tu sois encore à côté de moi. D’ici là, je garderai ceci.","sp":"Chaerin"},"D5_06_11":{"tx":"L’émission d’aujourd’hui, elle était comment ? Un petit mot, de la part de la personne qui a rempli le blanc.","sp":"Arin"},"D5_06_12":{"tx":"Dans le prochain script aussi, je laisserai un blanc. Parce que la personne qui le remplira est déjà décidée.","sp":"Arin"},"D5_06_13":{"tx":"Les lumières de la scène s’éteignent une à une. On plie les tentes, on empile les chaises.","sp":"Moi"},"D5_06_14":{"choices":["Regarder la scène qui s’éteint","Regarder la rue des stands qu’on range","Regarder le ciel où le soleil se couche"]},"D5_06_15":{"tx":"Cinq jours depuis mon transfert. Ce lycée qui m’était étranger me semble, aujourd’hui, un peu devenu ma place.","sp":"Moi"},"D5_06_16":{"tx":"À la fin du festival, c’est le visage de celle qui a passé le plus de temps avec moi aujourd’hui qui me revient.","sp":"Moi"},"END_SY_G01":{"tx":"Après le rangement de la clôture, Seoyeon m’a proposé d’aller prendre l’air un moment, sur les marches devant le toit.","sp":"Moi"},"END_SY_G02":{"tx":"Pour le travail d’aujourd’hui... non, pendant ces cinq jours entiers. Je suis contente d’avoir osé te demander.","sp":"Seoyeon"},"END_SY_G03":{"tx":"Moi, demander, je ne sais pas faire. Je croyais que c’était plus facile de tout faire seule.","sp":"Seoyeon"},"END_SY_G04":{"tx":"Mais quand je partage avec toi, {name}, ce n’est pas seulement le travail qui diminue.","sp":"Seoyeon"},"END_SY_G05":{"tx":"Le formulaire de partenariat pour le prochain festival, j’ai vu que mon nom y était déjà écrit.","sp":"Protagoniste"},"END_SY_G06":{"tx":"... Ça, c’est une place que je gardais pour l’écrire moi-même, la première.","sp":"Seoyeon"},"END_SY_G07":{"tx":"Aujourd’hui, du début à la fin, on l’a fait à deux. Le prochain festival aussi, faisons-le ensemble.","sp":"Seoyeon"},"END_SY_G08":{"tx":"Sur le formulaire, dans la lumière du couchant, les noms des deux sont écrits côte à côte.","sp":"Moi"},"END_SY_G09":{"tx":"Bonne fin de Seoyeon. Après les cours, avec toi.","sp":"Moi"},"END_SY_N01":{"tx":"Merci pour ton aide aujourd’hui. Pour ton adaptation, je n’ai plus à m’inquiéter, je crois.","sp":"Seoyeon"},"END_SY_N02":{"tx":"Le partenaire du festival, je l’ai choisi selon le planning de la classe. De façon à ce qu’on ne se surmène ni l’un ni l’autre.","sp":"Seoyeon"},"END_SY_N03":{"tx":"De bons camarades de classe. Cette distance, c’était exactement celle qui nous séparait.","sp":"Moi"},"END_SY_N04":{"tx":"Demain aussi, si tu te perds, viens me voir en premier. La règle ne change pas.","sp":"Seoyeon"},"END_SY_N05":{"tx":"Fin normale de Seoyeon. Les règles ne changent pas.","sp":"Moi"},"END_CH_G01":{"tx":"Après avoir remis le livre retrouvé sur son étagère, Chaerin m’a guidé jusqu’à la place près de la fenêtre.","sp":"Moi"},"END_CH_G02":{"tx":"Cette place, normalement, elle est pour une seule personne. Mais aujourd’hui, je vais y mettre une chaise de plus.","sp":"Chaerin"},"END_CH_G03":{"tx":"L’aînée enlève ses lunettes. Nos regards se croisent, longtemps, pour la première fois, bien en face.","sp":"Moi"},"END_CH_G04":{"tx":"« Sur un chemin nouveau, les pas d’un autre deviennent une carte », tu te souviens. Tes pas, à toi, je vais les apprendre par cœur.","sp":"Chaerin"},"END_CH_G05":{"tx":"La prochaine exposition aussi, préparons-la ensemble. La demande de partenariat, pour la bibliothèque, c’est moi qui la ferai la première.","sp":"Chaerin"},"END_CH_G06":{"tx":"Sur la place près de la fenêtre, il y a maintenant deux marque-pages.","sp":"Moi"},"END_CH_G07":{"tx":"Bonne fin de Chaerin. La place près de la fenêtre, pour deux.","sp":"Moi"},"END_CH_N01":{"tx":"Merci de m’avoir aidée à retrouver le livre. L’exposition s’est terminée sans problème.","sp":"Chaerin"},"END_CH_N02":{"tx":"Le marque-page, je l’ai bien reçu aujourd’hui. Retrouvons-nous quand j’ouvrirai le prochain livre. Lentement.","sp":"Chaerin"},"END_CH_N03":{"tx":"Un échange tranquille continuerait sans doute, mais la place près de la fenêtre restait, pour l’instant, pour une seule personne.","sp":"Moi"},"END_CH_N04":{"tx":"Fin normale de Chaerin. Au rythme d’une lecture lente.","sp":"Moi"},"END_AR_G01":{"tx":"Après la fin de l’émission de clôture, Arin déplie et me montre la dernière page de son carnet.","sp":"Moi"},"END_AR_G02":{"tx":"Je l’ai écrit là. Émission du festival, animée en duo avec {name}.","sp":"Arin"},"END_AR_G03":{"tx":"J’ai aussi reçu l’accord du club radio. Alors ça, ce n’est pas une réservation, c’est une confirmation.","sp":"Arin"},"END_AR_G04":{"tx":"Quand est-ce que tu as rendu les choses aussi grandes ?","sp":"Protagoniste"},"END_AR_G05":{"tx":"Que je suis du genre à foncer, tu le savais depuis le premier jour, non ? En échange, une promesse, je la tiens toujours.","sp":"Arin"},"END_AR_G06":{"tx":"En bas de la liste des promesses du carnet, une promesse que seuls deux connaissent s’est ajoutée.","sp":"Moi"},"END_AR_G07":{"tx":"Bonne fin d’Arin. Pas une réservation, une confirmation.","sp":"Moi"},"END_AR_N01":{"tx":"Émission du festival terminée. Ton aide d’aujourd’hui, je la laisserai dans le compte rendu de collaboration, officiellement.","sp":"Arin"},"END_AR_N02":{"tx":"L’émission du festival, ta voix aussi est passée à l’antenne. Mais l’animation, c’était mon rôle.","sp":"Arin"},"END_AR_N03":{"tx":"Animateur et invité interviewé. La relation n’a pas fait un pas de plus à partir de là.","sp":"Moi"},"END_AR_N04":{"tx":"Fin normale d’Arin. Un compte rendu officiel.","sp":"Moi"},"END_SOLO_01":{"tx":"Le festival est terminé. Jusqu’au bout, la préparation s’est faite en solitaire, au comité.","sp":"Moi"},"END_SOLO_02":{"tx":"Cinq jours depuis mon transfert. Je n’ai encore fait de promesse particulière à personne.","sp":"Moi"},"END_SOLO_03":{"tx":"En échange, je connais maintenant le plan du lycée par cœur, et les visages du couloir me sont devenus assez familiers.","sp":"Moi"},"END_SOLO_04":{"tx":"Le festival était chargé. Se rapprocher des gens, ce sera pour après.","sp":"Moi"},"END_SOLO_05":{"tx":"Le semestre de printemps ne fait que commencer. Il reste encore beaucoup de temps après les cours.","sp":"Moi"},"END_SOLO_06":{"tx":"Fin solo. Adaptation au semestre terminée.","sp":"Moi"},"N1_01":{"tx":"Vers le coucher du soleil, sur le chemin du retour, mon téléphone a vibré.","sp":"Moi"},"N1_02":{"tx":"(SMS) Merci pour le guide d’aujourd’hui. Demain matin, on se voit au portail. Pour que tu ne te perdes pas.","sp":"Seoyeon"},"N1_03":{"tx":"J’ai écrit une réponse, puis je l’ai effacée, deux fois. Ce n’était rien de spécial, mais bizarrement, ça me préoccupe.","sp":"Moi"},"N1_04":{"choices":["Répondre brièvement","Écrire longuement que je compte sur elle demain"]},"N1_05":{"tx":"(SMS) Demain, c’est l’annonce de l’interview, deuxième partie. Interdiction de fuir, d’accord ?","sp":"Arin"},"N1_06":{"tx":"Et dans mon sac, entre les pages du livre emprunté à Chaerin, un petit mot était glissé.","sp":"Moi"},"N1_07":{"tx":"(Mot) Ne pas commencer par la dernière page. La promesse, ne l’oublie pas.","sp":"Chaerin"},"N1_08":{"tx":"Je ne pensais pas que mon premier jour de transfert serait aussi long.","sp":"Moi"},"N1_09":{"tx":"Et pourtant, bizarrement, j’ai hâte d’être à demain.","sp":"Moi"},"N2_01":{"tx":"Le soir du deuxième jour. Après ma douche, je me suis allongé, mais le sommeil ne vient pas tout de suite.","sp":"Moi"},"N2_02":{"tx":"Sur mon téléphone, les notifications du groupe de la classe s’accumulent. Que des histoires de préparatifs du festival.","sp":"Moi"},"N2_03":{"tx":"(SMS) J’ai vu le compte rendu de réunion. Demain aussi, on partage. Pas en solo.","sp":"Seoyeon"},"N2_04":{"tx":"« Pas en solo. » Ces quelques mots tournent dans ma tête.","sp":"Moi"},"N2_05":{"choices":["Répondre tout de suite","Réfléchir longuement avant d’envoyer"]},"N2_06":{"tx":"(SMS) Demain midi, devant le studio radio. C’est un secret, rien que pour toi.","sp":"Arin"},"N2_07":{"tx":"Quand j’ouvre le marque-page sur mon bureau, la voix de Chaerin me revient.","sp":"Moi"},"N2_08":{"tx":"(Voix dans ma mémoire) « Sur un chemin qu’on emprunte pour la première fois, les pas d’un autre deviennent une carte. »","sp":"Chaerin"},"N2_09":{"tx":"Plus que trois jours avant le festival. J’ai le pressentiment que quelque chose va commencer.","sp":"Moi"},"N3_01":{"tx":"Le soir du troisième jour. La date limite pour les partenaires du festival, c’est demain.","sp":"Moi"},"N3_02":{"tx":"Les événements d’aujourd’hui me reviennent, dans le désordre. Le panneau d’affichage, la bibliothèque, le studio radio.","sp":"Moi"},"N3_03":{"tx":"(SMS) Demain, les papiers, on les fait ensemble jusqu’à la fin. C’est une promesse.","sp":"Seoyeon"},"N3_04":{"tx":"(SMS) Demain, c’est la prise finale. La promesse, je l’ai écrite dans mon carnet.","sp":"Arin"},"N3_05":{"tx":"(Mot) Le livre, rends-le-moi demain, à la place près de la fenêtre. Je t’attendrai.","sp":"Chaerin"},"N3_06":{"tx":"Le visage avec qui j’ai passé le plus de temps aujourd’hui sera sans doute encore là demain.","sp":"Moi"},"N3_07":{"choices":["Décider de me coucher tôt","Écrire chaque réponse avec soin, une par une"]},"N3_08":{"tx":"Quel que soit mon choix, le matin viendra vite.","sp":"Moi"},"N3_09":{"tx":"La veille du festival. Mon cœur bat un peu plus vite.","sp":"Moi"},"D4_01_01":{"tx":"Le matin de la veille du festival. Devant le portail, on accroche déjà les banderoles du festival.","sp":"Moi"},"D4_01_02":{"tx":"L’ambiance est différente aujourd’hui, pas vrai ? La veille d’un festival, l’air lui-même change.","sp":"Arin"},"D4_01_03":{"choices":["Avouer franchement que je suis tout excité","Dire que c’est comme d’habitude"]},"D4_01_04":{"tx":"Tout le monde est tout excité. Et pourtant, le travail d’aujourd’hui forme une montagne.","sp":"Seoyeon"},"D4_01_05":{"tx":"Festival J-1. À la fin de cette journée, les partenaires seront aussi décidés.","sp":"Moi"},"D4_02_01":{"tx":"Après les cours, la classe passe aussitôt en mode préparatifs du festival.","sp":"Moi"},"D4_02_02":{"tx":"La disposition des stands a changé. Il faut refaire les déplacements. Et aujourd’hui même, en plus.","sp":"Seoyeon"},"D4_02_03":{"tx":"Les mains de Seoyeon sont rapides, mais ses épaules sont encore plus tendues qu’hier.","sp":"Moi"},"D4_02_04":{"choices":["Proposer de m’occuper des déplacements","L’assister à côté, en suivant son rythme"]},"D4_02_05":{"tx":"... Si tu remarques toujours tout avant moi, comme ça, je vais finir par m’appuyer sur toi.","sp":"Seoyeon"},"D4_02_06":{"tx":"Alors... je peux m’appuyer ? Aujourd’hui, juste un peu.","sp":"Seoyeon"},"D4_02_07":{"tx":"Il a fallu quatre jours pour que la déléguée apprenne à s’appuyer sur quelqu’un.","sp":"Moi"},"D4_03_01":{"tx":"Pause déjeuner. La bibliothèque est silencieusement affairée avec les préparatifs de l’exposition du festival.","sp":"Moi"},"D4_03_02":{"tx":"L’ordre des livres de l’exposition, c’est mon dernier souci. Parce que le premier livre décide de l’impression.","sp":"Chaerin"},"D4_03_03":{"tx":"Le premier livre choisi par l’aînée, c’était celui que nous avions failli saisir ensemble, le premier jour de mon transfert.","sp":"Moi"},"D4_03_04":{"choices":["Dire que c’est bien ce livre-là","Dire que je fais confiance à son choix"]},"D4_03_05":{"tx":"Une première page, après tout, c’est mieux de l’ouvrir avec quelqu’un.","sp":"Chaerin"},"D4_03_06":{"tx":"Le marque-page que j’allais lui rendre, l’aînée le remet dans ma main.","sp":"Moi"},"D4_03_07":{"tx":"Demain, quand le festival sera terminé, rends-le-moi à ce moment-là. ... Attendre est devenu un plaisir.","sp":"Chaerin"},"D4_03_08":{"tx":"« Le plaisir d’attendre. » À ces mots, la pause déjeuner m’a paru bien courte.","sp":"Moi"},"D4_04_01":{"tx":"Juste avant la fin des cours. Au studio radio, la répétition de l’émission du festival bat son plein.","sp":"Moi"},"D4_04_02":{"tx":"Tu arrives juste au bon moment. Pour répéter le script, il me fallait un partenaire.","sp":"Arin"},"D4_04_03":{"tx":"Sur la dernière ligne du script, les noms des deux animateurs sont écrits côte à côte. L’un des deux est vide.","sp":"Moi"},"D4_04_04":{"choices":["Pointer le blanc et demander","Faire semblant de rien et lire le script"]},"D4_04_05":{"tx":"Ce blanc, il n’est pas encore confirmé. Demain, il pourrait se remplir.","sp":"Arin"},"D4_04_06":{"tx":"Alors demain, ne sois pas en retard. Parce que la première émission, je veux la commencer avec toi.","sp":"Arin"},"D4_04_07":{"tx":"La voix à travers le micro de répétition m’a semblé, aujourd’hui, étrangement proche.","sp":"Moi"},"D4_05_01":{"tx":"Après les cours. C’est le dernier carrefour de la veille du festival.","sp":"Moi"},"D4_05_02":{"tx":"Jusqu’à la clôture des demandes de partenariat, il ne reste vraiment plus de temps.","sp":"Moi"},"D4_05_03":{"choices":["Finir les derniers papiers avec Seoyeon","Achever les préparatifs de l’exposition avec Chaerin","Caler la répétition finale avec Arin"]},"D4_05_S1":{"tx":"C’est le dernier document. Quand ce sera fini, il ne restera vraiment que le festival.","sp":"Seoyeon"},"D4_05_S2":{"tx":"Demain, je laisserai la place à côté de moi libre. J’espère que le nom à écrire sur le formulaire est déjà décidé.","sp":"Seoyeon"},"D4_05_S3":{"tx":"Fidèle à quelqu’un qui choisit ses mots, c’était l’invitation la plus franche qui soit.","sp":"Moi"},"D4_05_C1":{"tx":"L’exposition est terminée. Ce qui reste, c’est de savoir avec qui on la regardera demain.","sp":"Chaerin"},"D4_05_C2":{"tx":"La chaise près de la fenêtre, demain, je vais en mettre deux. Tu viendras, n’est-ce pas ?","sp":"Chaerin"},"D4_05_C3":{"tx":"Au lieu de répondre, j’ai hoché la tête. Les yeux de l’aînée ont souri un peu.","sp":"Moi"},"D4_05_A1":{"tx":"Répétition finale terminée. Le rythme, il était parfait.","sp":"Arin"},"D4_05_A2":{"tx":"Demain, la première présentation de morceau, ce serait bien qu’elle commence avec ta voix. ... Tu le feras avec moi, n’est-ce pas ?","sp":"Arin"},"D4_05_A3":{"tx":"Le blanc dans le carnet ne quitte pas mon esprit. Demain, il sera rempli.","sp":"Moi"},"P03_04J":{"tx":"Je m’appelle {name}. C’est mon premier transfert, alors si vous riez, c’est déjà moitié réussi."},"P03_04R":{"tx":"... Cette blague est reçue. On comptera le trac comme déjà passé."},"D1_04_S1a":{"tx":"Une punaise change de main, et Seoyeon aligne l’affiche en partant du coin. Des mains qui connaissent l’ordre."},"D1_04_S2a":{"tx":"Si une personne transférée est aussi rapide, le travail de déléguée va finir par paraître louche."},"D1_04_S2b":{"tx":"Louche, c’est un grand mot. Quand même, le faire sans personne, c’était plus de travail que ça en avait l’air."},"D1_04_C1a":{"tx":"La question sur les goûts prend du temps. Elle ne presse pas. Elle aligne seulement les dos des livres."},"D1_04_C2a":{"tx":"Je viendrai demain. Je veux voir quels livres arrivent."},"D1_04_C2b":{"tx":"Cette curiosité suffit. Je laisserai la place près de la fenêtre libre."},"D1_04_A1a":{"tx":"La lumière devant le micro s’allume. Les yeux brillent avant la question."},"D1_04_A2a":{"tx":"Si cette réponse n’a pas à passer à l’antenne, c’est un soulagement."},"D1_04_A2b":{"tx":"Pas un soulagement. Un risque. Parce que je suis la seule à connaître cette réponse."},"D2_02_05W":{"tx":"... Si tu attends, dis-le. J’ai l’habitude de tout faire seule, alors je ne sais pas lire le silence à côté de moi."},"D2_02_05W2":{"tx":"Même alors, puisque tu es là, mes mains avancent. On peut regarder ensemble le brouillon du discours ?"},"D2_04_S1a":{"tx":"Trois jours. Sur le calendrier, la case du festival est plus proche qu’elle n’en avait l’air."},"D2_04_S2a":{"tx":"La moitié de l’ordre du jour de la prochaine réunion est déjà rangée. Juste les pages que tu as lues."},"D2_04_S2b":{"tx":"Seoyeon referme son stylo et sourit, petit. Un visage qui ne sort pas quand elle est seule."},"D2_04_C1a":{"tx":"On n’entend que les dos des livres qu’on aligne. Ce silence a l’air de lui convenir."},"D2_04_C2a":{"tx":"J’enlève cette étagère ? Ou on la laisse ?"},"D2_04_C2b":{"tx":"Laisse-la. Si tu l’enlèves, ce sera comme si la personne venue aujourd’hui n’avait jamais été là."},"D2_04_A1a":{"tx":"Le stylo d’Arin s’arrête avant la troisième question. Pour un entraînement, le regard est sérieux."},"D2_04_A2a":{"tx":"Tu t’en souviens, et tu ne le passes juste pas à l’antenne."},"D2_04_A2b":{"tx":"Oui. J’ai barré cette page en rouge. Privé. En gros."},"D3_02_05N":{"tx":"Prévenir, c’est juste. Mais le comité de la bibliothèque, c’est moi. Chercher ensemble ira plus vite."},"D3_04_S1a":{"tx":"Nous. Le mot reste avant le couvercle du carton."},"D3_04_S2a":{"tx":"Vérifie la dernière page. Aujourd’hui, moi aussi, j’ai besoin d’un deuxième regard."},"D3_04_S2b":{"tx":"À chaque tampon, les épaules de Seoyeon descendent un peu."},"D3_04_C1a":{"tx":"Ça sent la poussière. Elle glisse la main dans les rayons du bas comme si elle les connaissait."},"D3_04_C2a":{"tx":"Ce livre ira à la première place de l’exposition de demain. On l’a trouvé ensemble."},"D3_04_C2b":{"tx":"La couverture est tiède dans les mains. Un livre disparu puis revenu semble, aujourd’hui, étrangement léger."},"D3_04_A1a":{"tx":"Le voyant rouge se rallume. Ça ne ressemble pas à une répétition."},"D3_04_A2a":{"tx":"Si c’est écrit dans le carnet, ça devient une vraie promesse ?"},"D3_04_A2b":{"tx":"Oui. Le carnet du club radio est un contrat. Il est nul si on s’enfuit avant que l’encre sèche, cela dit."},"D5_02_16L":{"tx":"... D’accord. Va à la suite. Ici, je m’en charge."},"D5_02_16L2":{"tx":"Les pas tournent. Le merci reste, encore aujourd’hui, avalé."},"D5_03_16L":{"tx":"... Oui, vas-y. Je garde l’exposition. Il n’y a pas encore de raison d’enlever les lunettes."},"D5_03_16L2":{"tx":"La place près de la fenêtre reste pour une personne. Aujourd’hui, cette distance convient."},"D5_04_16L":{"tx":"... D’accord. La conclusion, je la fais seule. Le blanc, je le laisserai aussi la prochaine fois."},"D5_04_16L2":{"tx":"La porte du studio se ferme. Le voyant d’antenne est encore allumé."},"D5_05_S3a":{"tx":"Quand l’entrée et la sortie se séparent, les pas des gens s’alignent dans un seul sens."},"D5_05_S3b":{"tx":"Ce flux est le même que le plan qu’on a corrigé hier, tous les deux. Le papier est devenu réel."},"D5_05_C3a":{"tx":"Devant le panneau, quelqu’un lit l’avis à voix haute. Attendre fait aussi partie du festival."},"D5_05_C3b":{"tx":"Entendre dans la bouche de quelqu’un d’autre la phrase que tu as choisie, c’est étrange. Pas un mauvais étrange."},"D5_05_A3a":{"tx":"La foule qui attend lève la tête avec l’annonce. Les deux voix ne se chevauchent pas. Elles s’enchaînent."},"D5_05_A3b":{"tx":"Ce rythme, je veux l’utiliser aussi pour l’émission habituelle de demain. Le blanc est déjà à toi, cela dit."},"END_SY_G08a":{"tx":"Demain matin aussi, à la grille. Te montrer le chemin n’est peut-être plus une excuse."},"END_SY_G08b":{"tx":"Le coin du formulaire claque dans le vent. Les deux noms ne sont pas encore secs."},"END_SY_N03a":{"tx":"Par la fenêtre du couloir, on voit les tentes du festival qu’on replie. Aujourd’hui s’arrête là."},"END_SY_N03b":{"tx":"Demain, chacun son manuel. S’il te faut quand même les notes, dis-le."},"END_SY_N03c":{"tx":"D’accord. La règle est claire."},"END_SY_N03d":{"tx":"Seoyeon lève la main, à peine, et entre la première dans la salle. La distance reste. Demain est encore là."},"END_CH_G06a":{"tx":"Demain à midi, j’ouvre le carton des nouveautés. Le premier, on l’ouvre ensemble."},"END_CH_G06b":{"tx":"Je ne commencerai pas par la dernière page. La promesse tient toujours, non ?"},"END_CH_G06c":{"tx":"Elle tient. Et aujourd’hui, une ligne s’y est ajoutée. La place à côté."},"END_CH_N02a":{"tx":"La main qui reçoit le marque-page est brève et exacte. Elle ne retient pas davantage."},"END_CH_N02b":{"tx":"La chaise près de la fenêtre, demain encore, ce sera une seule. Mais je ne laisserai pas la porte fermée."},"END_CH_N02c":{"tx":"Alors je frapperai avant d’entrer."},"END_CH_N02d":{"tx":"Frapper, c’est bien. La bibliothèque aime les gens qui arrivent sans bruit."},"END_CH_N02e":{"tx":"Avant que les lumières s’éteignent, un regard en arrière. La place est encore pour une seule personne."},"END_AR_G05a":{"tx":"L’ouverture de l’émission de demain matin, c’est toi. Si tu es en retard, j’efface le blanc."},"END_AR_G05b":{"tx":"J’arriverai tôt, pour que tu ne l’effaces pas."},"END_AR_G05c":{"tx":"Le carnet se ferme dans un petit bruit. Le mot « confirmé » est déjà foncé."},"END_AR_N02a":{"tx":"Arin détache du cou sa carte de membre et la pose sur le bureau. L’émission est finie."},"END_AR_N02b":{"tx":"L’interview, deuxième partie, est en attente. Pas la réservation. C’est juste que la question suivante ne m’est pas encore venue."},"END_AR_N02c":{"tx":"Quand elle viendra, dis-le."},"END_AR_N02d":{"tx":"Je le dirai. Par le canal officiel. Les messages personnels... aujourd’hui, je me retiens."},"END_AR_N02e":{"tx":"Elle fait un petit salut et retourne ranger le matériel. Le carnet reste fermé."},"END_SOLO_04a":{"tx":"Dans les messages, il ne reste que de courts bonjours. Aucune phrase n’est assez épaisse pour s’appeler une promesse."},"END_SOLO_04b":{"tx":"Personne n’a laissé libre la place d’à côté. En échange, une journée d’école tient maintenant dans les mains."},"END_SOLO_04c":{"tx":"En passant la grille, une pensée : la prochaine fois après les cours, on peut choisir un peu plus près."},"N2_03G":{"tx":"(SMS) Bon travail aujourd’hui aussi. Demain matin, en classe."},"N2_04G":{"tx":"Un bonjour court. Et pourtant, la réponse ne part pas tout de suite."},"N2_06G":{"tx":"(SMS) Demain aussi, écoute l’émission de midi. Interdiction de fuir, toujours."},"N3_03G":{"tx":"(SMS) Bon travail aujourd’hui aussi. La date limite du partenaire, c’est demain. Ne force pas. Dors."},"N3_04G":{"tx":"(SMS) Si tu entends l’émission demain, fais juste un signe. Pour aujourd’hui, c’est tout."},"D4_05_S1a":{"tx":"La pointe du stylo s’arrête sur la dernière case. Seoyeon regarde par ici avant d’écrire un nom."},"D4_05_S2a":{"tx":"Je n’oblige pas. Mais si ça reste vide, je crois que je vais encore le remplir seule."},"D4_05_S2b":{"tx":"Au bout de cette phrase, la façon de s’appuyer apprise aujourd’hui s’accroche, un peu."},"D4_05_C1a":{"tx":"Sur la pancarte du premier livre, une phrase courte. La première page, à ouvrir ensemble."},"D4_05_C2a":{"tx":"Même si tu ne viens pas, l’exposition tourne. Mais cette chaise, je la mets en pensant à toi."},"D4_05_C2b":{"tx":"Ce n’est pas un ton qu’on refuse. Calme, mais chaque phrase laisse une place vide."},"D4_05_A1a":{"tx":"Le voyant d’antenne est éteint, mais la voix d’Arin est déjà à l’antenne."},"D4_05_A2a":{"tx":"Le blanc n’est pas encore fixé. Demain matin, je le verrouillerai peut-être à l’encre."},"D4_05_A2b":{"tx":"Elle le dit comme une blague, mais le coin du carnet est corné. Cette page a été ouverte plusieurs fois."}}};
